def test_ltwa_page_parses_rows(client, httpx_mock):
    httpx_mock.add_response(text=LTWA_HTML)
    page = client.ltwa.page(page=2, page_size=100, search="aachen", languages=["ger"])
    assert page.page == 2
    assert page.page_size == 100
    assert page.search == "aachen"
    assert page.languages == ["ger"]
    assert page.sort == "word"
    assert page.order == "asc"
    assert [entry.word for entry in page.entries] == [
        "Aabenraa",
        "Aachen",
        "Aachener",
        "aakkos-",
    ]
    assert last_params(httpx_mock) == [
        ("page", "2"),
        ("page_size", "100"),
        ("order", "asc"),
        ("sort", "word"),
        ("search", "aachen"),
        ("languages", "ger"),
    ]


